-- Integridad de la carga de diccionarios (Postgres 16 desechable, puerto 55437). Todas las filas deben dar 0.
select 'designaciones sin concepto' as chequeo, count(*) from terminology.concept_designations d left join terminology.catalog_concepts c on c.id=d.concept_id where c.id is null
union all select 'propiedades sin concepto', count(*) from terminology.concept_properties p left join terminology.catalog_concepts c on c.id=p.concept_id where c.id is null
union all select 'relaciones con origen inexistente', count(*) from terminology.concept_relationships r left join terminology.catalog_concepts c on c.id=r.source_concept_id where c.id is null
union all select 'relaciones con destino inexistente', count(*) from terminology.concept_relationships r left join terminology.catalog_concepts c on c.id=r.target_concept_id where c.id is null
union all select 'mapas con origen o destino inexistente', count(*) from terminology.concept_maps m left join terminology.catalog_concepts a on a.id=m.source_concept_id left join terminology.catalog_concepts b on b.id=m.target_concept_id where a.id is null or b.id is null
union all select 'conceptos sin version de code system', count(*) from terminology.catalog_concepts c left join terminology.code_system_versions v on v.id=c.code_system_version_id where v.id is null
union all select 'duplicados (version de code system, code)', count(*) from (select code_system_version_id, code from terminology.catalog_concepts group by 1,2 having count(*)>1) x
union all select 'conceptos con code nulo o vacio', count(*) from terminology.catalog_concepts where code is null or btrim(code)=''
union all select 'conceptos con display nulo o vacio', count(*) from terminology.catalog_concepts where display is null or btrim(display)=''
union all select 'designaciones con valor nulo o vacio', count(*) from terminology.concept_designations where value is null or btrim(value)=''
union all select 'designaciones duplicadas (concepto, idioma, tipo, valor)', count(*) from (select concept_id, language_concept_id, designation_type_concept_id, value from terminology.concept_designations group by 1,2,3,4 having count(*)>1) x
union all select 'conceptos de fuentes C7 sin dictionary-provenance', count(*) from terminology.catalog_concepts c join terminology.code_system_versions v on v.id=c.code_system_version_id join terminology.code_systems s on s.id=v.code_system_id where s.internal_code in ('chebi','protein-ontology','ncit-general','mesh','emdn','abremes-db') and not exists (select 1 from terminology.concept_properties p where p.concept_id=c.id and p.property_code='dictionary-provenance')
union all select 'provenance C7 sin sha256 o licencia', count(*) from terminology.concept_properties p join terminology.catalog_concepts c on c.id=p.concept_id join terminology.code_system_versions v on v.id=c.code_system_version_id join terminology.code_systems s on s.id=v.code_system_id where p.property_code='dictionary-provenance' and s.internal_code in ('chebi','protein-ontology','ncit-general','mesh','emdn','abremes-db') and (coalesce(p.value_json->>'fileSha256','')='' or coalesce(p.value_json->>'license','')='');
